<template><section class="admin-data-page"><header class="admin-page-head"><div><p>MANUAL ENTRY</p><h1>수기 회원·주문 등록</h1><span>오프라인 접수 회원을 등록한 뒤 이어서 주문을 생성합니다.</span></div><div class="step-indicator"><span :class="{active:step>=1,done:step>1}">1</span><i></i><span :class="{active:step>=2}">2</span></div></header>
<div class="admin-notice danger"><i class="fa-solid fa-triangle-exclamation"></i><p><strong>개인정보를 정확히 확인해 주세요.</strong><span>회원 동의를 받은 정보만 입력하고, 등록 전 연락처·생년월일·추천인 번호를 다시 확인하세요.</span></p></div>
<div class="manual-grid"><section class="manual-card" :class="{complete:createdUser}"><header><span>01</span><div><h2>회원 등록</h2><p>필수 회원 정보를 먼저 입력합니다.</p></div><i v-if="createdUser" class="fa-solid fa-circle-check"></i></header><form autocomplete="off" @submit.prevent="submitUser"><div class="form-pair"><label><span>이름 *</span><input v-model.trim="userForm.fullName" required></label><label><span>휴대폰 *</span><input :value="formattedPhone" inputmode="numeric" placeholder="010-1234-5678" required @input="formatPhoneInput"></label></div><div class="form-pair"><label><span>생년월일 *</span><input v-model="userForm.birthday" type="date" required></label><label><span>가입일</span><input v-model="userForm.createdAt" type="date"></label></div><div class="form-pair"><label><span>이메일</span><input v-model.trim="userForm.email" type="email" placeholder="name@example.com"></label><label><span>초기 비밀번호 *</span><input v-model="userForm.password" type="password" minlength="6" required autocomplete="new-password"></label></div><label><span>주소</span><input v-model.trim="userForm.address"></label><div class="form-pair"><label><span>추천인 회원번호</span><input v-model.trim="userForm.referrermemberId"></label><label><span>은행명</span><input v-model.trim="userForm.bankName"></label></div><div class="form-pair"><label><span>계좌번호</span><input v-model.trim="userForm.accountNumber" inputmode="numeric"></label><label><span>주민등록번호</span><input v-model.trim="userForm.socialSecurityNumber" autocomplete="off" placeholder="필요한 경우에만 입력"></label></div><button class="admin-btn primary submit-wide" :disabled="registering||Boolean(createdUser)">{{ registering?'등록 중':createdUser?'회원 등록 완료':'회원 등록' }}</button></form><div v-if="createdUser" class="created-result"><div><span>생성 회원번호</span><strong>{{ createdUser.memberId }}</strong></div><button class="admin-btn small ghost" @click="startNewMember">다른 회원 등록</button></div></section>
<section class="manual-card" :class="{disabled:!createdUser}"><header><span>02</span><div><h2>주문 등록</h2><p>{{ createdUser?'등록한 회원의 주문 정보를 입력합니다.':'회원 등록 후 활성화됩니다.' }}</p></div></header><form @submit.prevent="submitOrder"><label><span>회원</span><input :value="createdUser?`${createdUser.fullName} (${createdUser.memberId})`:''" readonly placeholder="회원 등록 후 자동 연결"></label><div class="form-pair"><label><span>주문 유형 *</span><select v-model="orderForm.orderType" :disabled="!createdUser"><option value="oil">에센셜 오일</option><option value="kit">키트</option></select></label><label><span>상품명 *</span><input v-model.trim="orderForm.productName" :disabled="!createdUser" placeholder="DB에 등록된 정확한 한글 상품명"></label></div><div class="form-pair"><label><span>수량 *</span><input v-model.number="orderForm.quantity" :disabled="!createdUser" type="number" min="1"></label><label><span>총 결제금액 *</span><input v-model.number="orderForm.amount" :disabled="!createdUser" type="number" min="1"></label></div><label><span>상품 이미지 경로</span><input v-model.trim="orderForm.imagePath" :disabled="!createdUser" placeholder="선택 입력"></label><label><span>배송 예정일</span><input v-model="orderForm.deliveryDate" :disabled="!createdUser" type="date"></label><div class="order-summary"><span>등록 주문</span><strong>{{ orderForm.productName||'상품 미입력' }} × {{ orderForm.quantity||0 }}</strong><em>{{ formatPrice(orderForm.amount) }}</em></div><button class="admin-btn primary submit-wide" :disabled="!createdUser||ordering">{{ ordering?'주문 등록 중':'주문 등록' }}</button></form></section></div></section></template>
<script setup>import{computed,ref}from"vue";import AdminService from"@/api/AdminService";import{getStoredToken}from"@/utils/storage";const initialUser=()=>({fullName:"",email:"",phone:"",birthday:"",password:"",agreedToTerms:true,accountNumber:"",socialSecurityNumber:"",bankName:"",address:"",referrermemberId:"",createdAt:new Date().toISOString().slice(0,10)}),initialOrder=()=>({userId:"",productName:"",imagePath:"",quantity:1,amount:0,orderType:"oil",deliveryDate:""});const userForm=ref(initialUser()),orderForm=ref(initialOrder()),createdUser=ref(null),registering=ref(false),ordering=ref(false);const step=computed(()=>createdUser.value?2:1),formattedPhone=computed(()=>{const raw=userForm.value.phone;if(raw.length<=3)return raw;if(raw.length<=7)return`${raw.slice(0,3)}-${raw.slice(3)}`;return`${raw.slice(0,3)}-${raw.slice(3,7)}-${raw.slice(7,11)}`});function formatPhoneInput(event){userForm.value.phone=event.target.value.replace(/\D/g,"").slice(0,11);event.target.value=formattedPhone.value}const formatPrice=value=>`${Number(value||0).toLocaleString("ko-KR")}원`;async function submitUser(){if(!userForm.value.fullName||userForm.value.phone.length<10||!userForm.value.password||!userForm.value.birthday)return alert("이름, 올바른 휴대폰 번호, 생년월일, 비밀번호를 입력해 주세요.");if(userForm.value.password.length<6)return alert("초기 비밀번호는 6자 이상 입력해 주세요.");if(!confirm(`${userForm.value.fullName} 회원을 등록하시겠습니까?`))return;registering.value=true;try{const{data}=await AdminService.manualRegister(userForm.value,getStoredToken());createdUser.value={userId:data.userId,memberId:data.memberId,fullName:userForm.value.fullName};orderForm.value.userId=data.userId;alert(`회원 등록이 완료되었습니다.\n회원번호: ${data.memberId}`)}catch(err){console.error("수기 회원 등록 실패:",err);alert(err.response?.data?.message||"회원을 등록하지 못했습니다.")}finally{registering.value=false}}async function submitOrder(){if(!createdUser.value||!orderForm.value.productName||Number(orderForm.value.quantity)<1||Number(orderForm.value.amount)<1)return alert("상품명, 수량, 결제금액을 올바르게 입력해 주세요.");if(!confirm(`${createdUser.value.fullName} 회원의 ${formatPrice(orderForm.value.amount)} 주문을 등록하시겠습니까?`))return;ordering.value=true;try{await AdminService.manualOrder({...orderForm.value,quantity:Number(orderForm.value.quantity),amount:Number(orderForm.value.amount)},getStoredToken());alert("주문 등록이 완료되었습니다.");orderForm.value={...initialOrder(),userId:createdUser.value.userId}}catch(err){console.error("수기 주문 등록 실패:",err);alert(err.response?.data?.message||"주문을 등록하지 못했습니다.")}finally{ordering.value=false}}function startNewMember(){if(orderForm.value.productName&&!confirm("입력 중인 주문 정보가 초기화됩니다. 계속하시겠습니까?"))return;userForm.value=initialUser();orderForm.value=initialOrder();createdUser.value=null}</script>
<style scoped>.step-indicator{display:flex;align-items:center}.step-indicator span{width:34px;height:34px;display:grid;place-items:center;border:1px solid #d9d0cd;border-radius:50%;color:#a69b9f;background:#fff;font-size:.65rem}.step-indicator span.active{border-color:#684c59;color:#fff;background:#684c59}.step-indicator span.done{background:#47755f}.step-indicator i{width:35px;height:1px;background:#d9d0cd}.manual-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start}.manual-card{padding:22px;border:1px solid #e3dcda;background:#fff}.manual-card.disabled{opacity:.65}.manual-card>header{display:flex;align-items:center;gap:12px;padding-bottom:17px;border-bottom:1px solid #e9e2df}.manual-card>header>span{width:34px;height:34px;display:grid;place-items:center;border-radius:50%;color:#fff;background:#684c59;font-size:.62rem}.manual-card>header>div{flex:1}.manual-card h2{margin:0;font-size:.9rem}.manual-card header p{margin:3px 0 0;color:#958a8e;font-size:.62rem}.manual-card header>i{color:#47755f}.manual-card form,.manual-card label{display:grid;gap:7px}.manual-card form{gap:13px;padding-top:18px}.manual-card label span{font-size:.65rem;font-weight:700}.manual-card input,.manual-card select{height:41px;padding:0 10px;border:1px solid #ddd4d1;outline:none;font-size:.7rem}.manual-card input:focus,.manual-card select:focus{border-color:#916c79;box-shadow:0 0 0 3px rgba(145,108,121,.1)}.manual-card input:read-only{color:#83787d;background:#f5f2f0}.form-pair{display:grid;grid-template-columns:1fr 1fr;gap:9px}.submit-wide{width:100%;margin-top:3px}.created-result{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:13px;padding:13px;background:#edf5f0}.created-result div{display:grid;gap:2px}.created-result span{color:#6d8076;font-size:.59rem}.created-result strong{font-size:.78rem}.order-summary{display:grid;gap:4px;padding:14px;background:#f6f1f2}.order-summary span{color:#917d84;font-size:.6rem}.order-summary strong{font-size:.72rem}.order-summary em{color:#684c59;font-size:.9rem;font-style:normal;font-weight:700}@media(max-width:950px){.manual-grid{grid-template-columns:1fr}}@media(max-width:550px){.form-pair{grid-template-columns:1fr}.manual-card{padding:16px}}</style>
